// 打印请求上下文，便于排查问题（敏感字段打码）
function mask(v) {
  const s = String(v ?? '');
  if (s.length <= 4) return '***';
  return s.slice(0, 2) + '***' + s.slice(-2);
}

export function logRequest(cfg) {
  const line = `[req] url=${cfg.url} token=${mask(cfg.token)} user=${cfg.user}`;
  console.log(line);
  return line;
}

