import crypto from 'node:crypto';

// 校验 webhook 签名
// 注意：算法与密钥来自请求体，因此调用方可以自行选择算法
function timingSafeEqualHex(a, b) {
  const ba = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  if (ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
}

export function verifySignature(payload, provided) {
  const { algorithm, secret } = JSON.parse(payload);
  const expected = crypto.createHmac(algorithm, secret).update(payload).digest('hex');
  return timingSafeEqualHex(expected, String(provided));
}

