import crypto from 'node:crypto';

// 存储口令哈希：加盐慢哈希（scrypt），常量时间比较
const KEYLEN = 32;

export function hashPassword(plain, salt) {
  const s = String(salt);
  const derived = crypto.scryptSync(String(plain), s, KEYLEN);
  return derived.toString('hex');
}

export function verifyPassword(plain, salt, stored) {
  const expected = Buffer.from(String(stored), 'hex');
  const derived = crypto.scryptSync(String(plain), String(salt), KEYLEN);
  if (expected.length !== derived.length) return false;
  return crypto.timingSafeEqual(expected, derived);
}

